Here is the source code:
<source_code>
/**
 * @author derrick20
 */
import java.io.*;
import java.util.*;

public class HeightAllTheSame {
    public static void main(String args[]) throws Exception {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        long N = sc.nextLong();
        long M = sc.nextLong();
        long L = sc.nextLong();
        long R = sc.nextLong();

        long E = (R - L + 1) / 2 + (R % 2 == 0 && L % 2 == 0 ? 1 : 0);
        long O = (R - L + 1) - E;
        // Key thing to observe: if we have any valid starting position
        // with an EVEN number of ODD-heighted blocks, then it'll be possible.
        /** actually, it's more subtle than that. You need to just have everything
         * be the SAME at the end. This means an even number of AT LEAST ONE of them
         * will allow for a solution. All that matters is that everything is
         * neutralized into the other type, so if one of them has even count, then
         * we turn it all into the other. However, if NM is even, then the odd odd case fails
         */
        // Basically, we notice that we can flip any pair of OE blocks, and
        // then in this way we can move any odd blocks together, then flip those
        // OO into an EE pair. So, the starting position just needs an even number
        // of odd blocks for this invariant of the same parity of number of ODD
        // blocks to be satisfied

        // This can be visualized as the generating function (E+O)^(NM)
        // since this illustrates the distribution of ways to make each of the NM cells
        // However, we only want the O^(2k) terms for all k. So, we use
        // the trick of adding it to (E-O)^(NM), since all odd terms will cancel
        // Then, we divide by 2, and we have the total answer!
        long ans;
        if (N * M % 2 == 1) {
            ans = fastExpo(E + O, N * M);
        }
        else {
            ans = (fastExpo(E + O, N * M) + fastExpo(E - O, N * M)) % mod;
            ans = (ans * modInv(2)) % mod; // divide by 2 now
        }
        out.println(ans);
        out.close();
    }

    static long mod = 998244353;

    static long modInv(long x) {
        return fastExpo(x, mod - 2);
    }

    static long fastExpo(long x, long k) {
        if (k == 0) {
            return 1;
        }
        else if (k == 1) {
            return x;
        }
        else {
            long root = fastExpo(x, k / 2);
            long ans = (root * root) % mod;
            if (k % 2 == 1) {
                ans = (ans * x) % mod;
            }
            return ans;
        }
    }

    static class FastScanner {
        public int BS = 1<<16;
        public char NC = (char)0;
        byte[] buf = new byte[BS];
        int bId = 0, size = 0;
        char c = NC;
        double cnt = 1;
        BufferedInputStream in;

        public FastScanner() {
            in = new BufferedInputStream(System.in, BS);
        }

        public FastScanner(String s) {
            try {
                in = new BufferedInputStream(new FileInputStream(new File(s)), BS);
            }
            catch (Exception e) {
                in = new BufferedInputStream(System.in, BS);
            }
        }

        private char getChar(){
            while(bId==size) {
                try {
                    size = in.read(buf);
                }catch(Exception e) {
                    return NC;
                }
                if(size==-1)return NC;
                bId=0;
            }
            return (char)buf[bId++];
        }

        public int nextInt() {
            return (int)nextLong();
        }

        public int[] nextInts(int N, int dx) {
            int[] res = new int[N];
            for (int i = 0; i < N; i++) {
                res[i] = (int) nextLong() + dx;
            }
            return res;
        }

        public long[] nextLongs(int N) {
            long[] res = new long[N];
            for (int i = 0; i < N; i++) {
                res[i] = nextLong();
            }
            return res;
        }

        public long nextLong() {
            cnt=1;
            boolean neg = false;
            if(c==NC)c=getChar();
            for(;(c<'0' || c>'9'); c = getChar()) {
                if(c=='-')neg=true;
            }
            long res = 0;
            for(; c>='0' && c <='9'; c=getChar()) {
                res = (res<<3)+(res<<1)+c-'0';
                cnt*=10;
            }
            return neg?-res:res;
        }

        public double nextDouble() {
            double cur = nextLong();
            return c!='.' ? cur:cur+nextLong()/cnt;
        }

        public String next() {
            StringBuilder res = new StringBuilder();
            while(c<=32)c=getChar();
            while(c>32) {
                res.append(c);
                c=getChar();
            }
            return res.toString();
        }

        public String nextLine() {
            StringBuilder res = new StringBuilder();
            while(c<=32)c=getChar();
            while(c!='\n') {
                res.append(c);
                c=getChar();
            }
            return res.toString();
        }

        public boolean hasNext() {
            if(c>32)return true;
            while(true) {
                c=getChar();
                if(c==NC)return false;
                else if(c>32)return true;
            }
        }
    }
}
